public void bonAppetit(int[] bill, int k, int b) {
    int annaShare = 0;
    for (int i = 0; i < bill.length; i++) {
        if (i != k) {                 // skip the item Anna did not eat
            annaShare += bill[i];
        }
    }
    annaShare /= 2;                   // split the shared cost evenly
    if (annaShare == b) {
        System.out.println("Bon Appetit");
    } else {
        System.out.println(b - annaShare);
    }
}

