code.java:
public void bonAppetit(int[] bill, int k, int b) {
    int total = 0;
    for (int cost : bill) {
        total += cost;               // sum everything, no branch
    }
    int fair = (total - bill[k]) / 2;  // remove skipped item, then halve
    if (fair == b) {
        System.out.println("Bon Appetit");
    } else {
        System.out.println(b - fair);
    }
}

